const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const windhoek = ee.Geometry.Point([17.0832, -22.5700]); // Windhoek coordinates
  const region = windhoek.buffer(5000); // 5km buffer around Windhoek

  // Define the two comparison dates
  const date2020 = '2020-01-29';
  const date2021 = '2021-02-07';

  // 2. Data Acquisition - Sentinel-2 with cloud masking
  function getS2Image(date) {
    const startDate = ee.Date(date);
    const endDate = startDate.advance(1, 'day');

    const collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(region)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));

    // Apply cloud masking
    function maskClouds(image) {
      const qa = image.select('QA60');
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return image.updateMask(mask);
    }

    const maskedCollection = collection.map(maskClouds);
    return maskedCollection.median().clip(region);
  }

  // Get images for both dates
  const img2020 = getS2Image(date2020);
  const img2021 = getS2Image(date2021);

  // Check if collections are empty
  const count2020 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(region)
    .filterDate('2020-01-29', '2020-01-30')
    .size();
  const count2021 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(region)
    .filterDate('2021-02-07', '2021-02-08')
    .size();

  const count2020Info = count2020.getInfo();
  const count2021Info = count2021.getInfo();

  print(`2020-01-29 Images: ${count2020Info}`);
  print(`2021-02-07 Images: ${count2021Info}`);

  if (count2020Info === 0 || count2021Info === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // Calculate NDVI
  function calculateNDVI(image) {
    return image.normalizedDifference(['B8', 'B4']).rename('NDVI');
  }

  const ndvi2020 = calculateNDVI(img2020);
  const ndvi2021 = calculateNDVI(img2021);

  // Get pixel counts and mean NDVI
  const stats2020 = ndvi2020.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 100,
    maxPixels: 1e9
  });

  const stats2021 = ndvi2021.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 100,
    maxPixels: 1e9
  });

  const mean2020 = stats2020.get('NDVI_mean').getInfo();
  const count2020px = stats2020.get('NDVI_count').getInfo();
  const mean2021 = stats2021.get('NDVI_mean').getInfo();
  const count2021px = stats2021.get('NDVI_count').getInfo();

  print(`2020 NDVI: ${mean2020?.toFixed(4) || 'null'}, Pixels: ${count2020px}`);
  print(`2021 NDVI: ${mean2021?.toFixed(4) || 'null'}, Pixels: ${count2021px}`);

  // Check for valid pixels
  if (count2020px === 0 || count2021px === 0) {
    print("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (mean2020 === null || mean2021 === null || 
      isNaN(mean2020) || isNaN(mean2021) ||
      mean2020 > 1 || mean2021 > 1 || mean2020 < -1 || mean2021 < -1) {
    print("<answer>C3</answer>");
    return;
  }

  // Final comparison
  if (mean2021 > mean2020) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
